{"Table":"bk_tb_parameter_values","Create Table":"CREATE TABLE `bk_tb_parameter_values` (\n  `id` varchar(36) NOT NULL,\n  `parameter` varchar(255) DEFAULT NULL,\n  `owner` varchar(255) NOT NULL,\n  `value` varchar(255) NOT NULL,\n  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),\n  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),\n  PRIMARY KEY (`id`),\n  KEY `FK_parameter_value` (`parameter`),\n  KEY `idx_parameter_owner` (`owner`),\n  CONSTRAINT `FK_parameter_owner` FOREIGN KEY (`owner`) REFERENCES `bk_tb_user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,\n  CONSTRAINT `FK_parameter_value` FOREIGN KEY (`parameter`) REFERENCES `bk_tb_parameters` (`id`) ON DELETE CASCADE ON UPDATE CASCADE\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci","json":{"name":"bk_tb_parameter_values.sql","path":"files/sql/rod/bk_tb_parameter_values.sql","sha":"d1836e01dcb14a85ff6a98ce3a8f0e134cabe01a","size":1307219,"url":"https://api.github.com/repos/rodcordeiro/shares/contents/files/sql/rod/bk_tb_parameter_values.sql?ref=master","html_url":"https://github.com/rodcordeiro/shares/blob/master/files/sql/rod/bk_tb_parameter_values.sql","git_url":"https://api.github.com/repos/rodcordeiro/shares/git/blobs/d1836e01dcb14a85ff6a98ce3a8f0e134cabe01a","download_url":"https://raw.githubusercontent.com/rodcordeiro/shares/master/files/sql/rod/bk_tb_parameter_values.sql","type":"file","content":"","encoding":"none","_links":{"self":"https://api.github.com/repos/rodcordeiro/shares/contents/files/sql/rod/bk_tb_parameter_values.sql?ref=master","git":"https://api.github.com/repos/rodcordeiro/shares/git/blobs/d1836e01dcb14a85ff6a98ce3a8f0e134cabe01a","html":"https://github.com/rodcordeiro/shares/blob/master/files/sql/rod/bk_tb_parameter_values.sql"}},"pairedItem":{"item":11},"index":11}